import * as React from "react"

/*
 * Example data for the Logo Cloud blocks: the 34 marks of Figma's Brand Logos
 * set (43444:219984), copied from its SVG exports. No block ships a brand:
 * the docs previews and the Storybook stories pass these in as `logos`.
 *
 * Each mark keeps the colour mode Figma gives it, in both themes; nothing
 * switches with the theme. `original` keeps the brand's own colours, which
 * is why they live here and never in a block. Where Figma binds a part to a
 * token instead of a hex (the near-black wordmarks of Uber, IBM or Amazon,
 * Microsoft's grey wordmark), the part takes that token here too, so it turns
 * light in dark mode while the brand colours stay. `monochrome` draws every
 * shape in `currentColor`: Figma binds it to `muted-foreground`, and the
 * block's logo slot sets that colour (or `foreground-inverse` on an inverted
 * surface, as Figma's instances do there).
 */

type Gradient = { x1: number; y1: number; x2: number; y2: number; stops: [offset: number, color: string][] }
/** A theme token Figma binds a shape to, in place of a hex. */
type Token = "foreground" | "muted-foreground"
/** A shape: its path, its fill (a hex, a theme token, or an index into `gradients`) and whether it fills even-odd. */
type Shape = [d: string, fill: string | number, evenOdd?: boolean]

/** The token fills as classes, so they follow the theme. */
const TOKEN_FILL: Record<Token, string> = { foreground: "fill-foreground", "muted-foreground": "fill-muted-foreground" }
const isToken = (value: string | number): value is Token => typeof value === "string" && value in TOKEN_FILL
type Mark = { name: string; width: number; height: number; gradients?: Gradient[]; paths: Shape[] }

