export type Brand = keyof typeof MARKS
export type BrandColor = "original" | "monochrome"

export interface BrandLogoProps extends React.SVGProps<SVGSVGElement> {
  brand: Brand
  /**
   * Figma's `Color`: the brand's own colours, or every shape in `currentColor`.
   * @default "original"
   */
  color?: BrandColor
}

/** One mark at Figma's size (24px tall), hidden from assistive tech: the block names it. */
export function BrandLogo({ brand, color = "original", ...props }: BrandLogoProps) {
  const mark: Mark = MARKS[brand]
  // A gradient is looked up by id, so each mark on the page needs its own.
  const id = React.useId().replace(/[^a-zA-Z0-9_-]/g, "")
  const mono = color === "monochrome"

  return (
    <svg
      viewBox={`0 0 ${mark.width} ${mark.height}`}
      width={mark.width}
      height={mark.height}
      fill="none"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {!mono && mark.gradients ? (
        <defs>
          {mark.gradients.map((gradient, index) => (
            <linearGradient key={index} id={`${id}-${index}`} x1={gradient.x1} y1={gradient.y1} x2={gradient.x2} y2={gradient.y2} gradientUnits="userSpaceOnUse">
              {gradient.stops.map(([offset, stopColor]) => (
                <stop key={offset} offset={offset} stopColor={stopColor} />
              ))}
            </linearGradient>
          ))}
        </defs>
      ) : null}
      {mark.paths.map(([d, value, evenOdd], index) => (
        <path
          key={index}
          d={d}
          fill={mono ? "currentColor" : isToken(value) ? undefined : typeof value === "number" ? `url(#${id}-${value})` : value}
          className={!mono && isToken(value) ? TOKEN_FILL[value] : undefined}
          fillRule={evenOdd ? "evenodd" : undefined}
          clipRule={evenOdd ? "evenodd" : undefined}
        />
      ))}
    </svg>
  )
}

/** A Logo Cloud logo: the brand's name, which the block gives screen readers, and its mark. */
export const brandLogo = (brand: Brand, color: BrandColor = "original") => ({
  name: MARKS[brand].name,
  logo: <BrandLogo brand={brand} color={color} />,
})

/** Several, in the order given. */
export const brandLogos = (brands: Brand[], color: BrandColor = "original") => brands.map((brand) => brandLogo(brand, color))
